name?: string, // maxLength: 250
// Nodes to add to the graph.
// maxItems: 100
addNodes?: Array<
{
// Caller-chosen temporary id for this node (e.g. "node_1"); addEdges/removeEdges in this same call may reference it as source/target. The server resolves it to a real id and returns the mapping in `refIdMap`.
refId: string, // minLength: 1
// An `id` from weave_get_node_catalog.
nodeTypeId: string, // minLength: 1
// Node data, keyed by the node type's `settableData` from weave_get_node_catalog.
data?: { [key: string]: any },
// Node params, keyed by the node type's `settableParams` from weave_get_node_catalog.
params?: { [key: string]: any },
// Node title shown on canvas. Pass it here, not inside `data`, where it is dropped.
displayName?: string, // maxLength: 150
// Canvas position, relative to the group when `parentId` is set. Nodes render about 460 wide and up to 700 tall, taller for an import showing a portrait image: place columns 650 apart and stacked nodes 800 apart, clear of the `at=` positions in the weave_get_workflow outline. To replace a node, pass the removed node's `position` and `parentId` from weave_get_workflow. Omit to place the node beside its group's children, or right of the graph.
position?: {
// Canvas x coordinate.
x: number,
// Canvas y coordinate.
y: number,
},
// Id of an existing group (a `custom_group` node) to add this node into. Without a `position`, core places it beside the group's children; the group grows to fit.
parentId?: string, // minLength: 1
}
>,
// Nodes to copy with their data, params and generated outputs, as Duplicate does on the canvas; use this, not addNodes, which starts a node without the original's outputs. Groups and Figma nodes are not copied.
// maxItems: 100
duplicateNodes?: Array<
{
// Caller-chosen temporary id for the copy; addEdges in this same call may reference it, and `refIdMap` returns its real id.
refId: string, // minLength: 1
// Id of the node already in the workflow to copy.
id: string, // minLength: 1
// Canvas position, relative to the source's group when it has one. Omit to place the copy beside its group's children, or right of the graph.
position?: {
// Canvas x coordinate.
x: number,
// Canvas y coordinate.
y: number,
},
}
>,
// Edits to nodes already in the graph.
// maxItems: 100
updateNodes?: Array<
{
// Id of a node already in the workflow. Not a refId: an edit never creates a node.
id: string, // minLength: 1
// Node data to set, keyed by the node type's `settableData`. Only the keys you pass change. `generations` takes `{ remove?: [ids], select?: id }`, ids from weave_get_workflow; removal applies first. Confirm removals with the user. On a `custom_group`, `color` (#rrggbb or the default rgba) recolors the frame.
data?: { [key: string]: any },
// Node params to set, keyed by the node type's `settableParams`. Only the keys you pass change; null clears one.
params?: { [key: string]: any },
// New node title shown on canvas.
displayName?: string, // maxLength: 150
// Canvas position to move the node to, relative to its group when it has a `parentId`.
position?: {
// Canvas x coordinate.
x: number,
// Canvas y coordinate.
y: number,
},
}
>,
// Edges to add to the graph, wiring together existing and/or newly-added nodes.
// maxItems: 100
addEdges?: Array<
{
// Source node id, or a refId minted by this call's addNodes or duplicateNodes.
source: string,
// Bare source handle name (not the ReactFlow composite form).
sourceHandle: string,
// Target node id, or a refId minted by this call's addNodes or duplicateNodes.
target: string,
// Bare target handle name (not the ReactFlow composite form).
targetHandle: string,
}
>,
// Ids of nodes to remove from the graph.
removeNodes?: string[], // maxItems: 100
// Edges to remove from the graph.
// maxItems: 100
removeEdges?: Array<
{
// Source node id or refId of the edge to remove.
source: string,
// Target node id or refId of the edge to remove.
target: string,
// Bare target handle name of the edge to remove.
targetHandle: string,
}
>,
// Groups to create, each wrapping the given nodes. Group each distinct stage of a larger workflow (e.g. inputs, generation, post-processing); leave a workflow of a few nodes ungrouped. Groups do not nest, and a node already in a group must be ungrouped first.
// maxItems: 100
groupNodes?: Array<
{
// Caller-chosen temporary id for the new group; `refIdMap` returns its real id.
refId: string, // minLength: 1
// Group label shown on canvas, named for what its nodes do together.
name: string, // minLength: 1, maxLength: 150
// Ids of nodes to wrap, or refIds minted by this call's addNodes or duplicateNodes.
// minItems: 1, maxItems: 100
nodeIds: Array<
string // minLength: 1
>,
// Frame color as #rrggbb, or the default rgba(227, 232, 236, 0.64). Set one on every group, distinct from the other groups, fitting its stage.
color?: string, // pattern: /^(#[0-9a-fA-F]{6}|rgba\(227, 232, 236, 0\.64\))$/
}
>,
// Ids of groups to dissolve; their children stay where they are on canvas. Use this, not `removeNodes`, which also deletes the children.
// maxItems: 100
ungroupNodes?: Array<
string // minLength: 1
>,
}): Promise<unknown>;
```

