enterprise?: Array<"default" | "anon" | "zdr">,
// Hostnames to leave out of results. Mutually exclusive with includeDomains.
excludeDomains?: Array<
string // minLength: 1, maxLength: 253, pattern: /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$/
