excludeTags?: string[],
formats?: Array<"markdown" | "html" | "rawHtml" | "screenshot" | "links" | "images" | "summary" | "changeTracking" | "branding" | "json" | "query" | "audio">,
includeTags?: string[],
jsonOptions?: { prompt?: string, schema?: { [key: string]: any } },
location?: { country?: string, languages?: string[] },
lockdown?: boolean,
maxAge?: number,
mobile?: boolean,
onlyMainContent?: boolean,
parsers?: Array<"pdf">,
pdfOptions?: {
maxPages?: integer, // minimum: 1, maximum: 10000
},
// Loads a saved browser profile without saving changes to it.
profile?: { name: string },
proxy?: "basic" | "stealth" | "enhanced" | "auto",
queryOptions?: {
