// The user's underlying goal in one sentence, not a restatement of this call's arguments. Reuse it across related calls. Firecrawl uses it to learn what agents need and improve its results. No personal data, secrets or the user's exact words.
objective: string, // minLength: 1, maxLength: 1000
// People to enrich. People and companies together are at most 10 per call.
people?: Array<{ linkedin_url: any } | { email: any } | { phone: any } | { company: any, name: any } | { domain: any, name: any } | { company: any, first_name: any, last_name: any } | { domain: any, first_name: any, last_name: any }>, // minItems: 1, maxItems: 10
