// The provider's own response, unchanged.
data: any,
provider: string,
[key: string]: any,
}
>,
[key: string]: any,
}
>,
// Credits charged: the listed price of each provider that found something.
credits_used?: number,
// The cap set for the call; absent when uncapped.
max_credits?: number,
people?: Array<
{
// Per filled field (work_email, personal_email, mobile, profile, firmographics), what backs the answer.
// Additional JSON Schema constraints: propertyNames={"type": "string"}
fields?: {
[key: string]: {
// Profile or firmographics: false when no provider gave the whole answer and this is the best partial one.
complete?: boolean,
// Work email: the address is on the company's domain.
domain_match?: boolean,
// Firmographics: the company LinkedIn page matches the company's domain or name.
linkedin_confirmed?: boolean,
provider: string,
// The email address chosen from that provider's response.
value?: string,
// Email: the provider marked the address deliverable.
verified?: boolean,
[key: string]: any,
},
},
// Index into the people or companies list.
input_index: number,
// One entry per provider that found a requested field; empty when none did.
results: Array<
{
// The provider's own response, unchanged.
data: any,
provider: string,
[key: string]: any,
}
>,
[key: string]: any,
