}
 | {
// flow_start_attachment_upload 가 준 uploadToken. PUT 을 마친 뒤에 쓴다. 파일명은 그때 준 이름이 쓰인다.
uploadToken: string, // pattern: /^[A-Za-z0-9_-]{43}$/
}

>,
// 첨부 이미지. 지정하면 단건(tasks 1개)만 가능하다.
imageFiles?: Array<

 | {
// 경로문자(\ / : * ? " < > |) 금지.
fileName: string, // minLength: 1, maxLength: 100
// 실제 파일 바이트를 읽어 변환한 base64. 임의 생성·data URI prefix·줄바꿈 금지.
fileContents: string, // minLength: 1
}
 | {
// flow_start_attachment_upload 가 준 uploadToken. PUT 을 마친 뒤에 쓴다. 파일명은 그때 준 이름이 쓰인다.
uploadToken: string, // pattern: /^[A-Za-z0-9_-]{43}$/
}

>,
// 공개 범위. 지정하면 단건만 가능하다.
viewPermission?: "all" | "admin",
// 봇 계정으로 등록할 때. 이메일 형식. 지정하면 단건만 가능하다.
botId?: string, // minLength: 1, maxLength: 100, pattern: /^[a-z0-9\-@.]+$/
}
>,
