// minItems: 1, maxItems: 8
keywords?: Array<
string // minLength: 1, maxLength: 50
>,
// 검색 다음 페이지 커서(이전 응답 nextCursor).
nextCursor?: string,
// 검색 정렬(keywords 와 함께).
