lastCursor: string | null,
messages: { attachments?: { attachId: string, attachUrl: string | null, fileName: string, fileSize: number, type?: "image" | "file" }[], contents?: string | null, messageId: string, registerId?: string | null, registerName?: string | null, registeredDateTime?: string | null }[],
}>;
